// Parse: /robot say Hello world  OR  /robot wave  OR  /robot emoji 90
const text = ($json.body?.text || $json.body?.command || '').trim();
const parts = text.split(/\s+/);
const cmd = (parts[0] || '').toLowerCase();
const arg = parts.slice(1).join(' ');

let action = null;
let params = {};
let response = '';

if (cmd === 'say' || cmd === 'speak' || cmd === 'tts') {
  action = 'tts';
  params = { text: arg || 'Hello from Slack!' };
  response = `Speaking: "${params.text}"`;
} else if (cmd === 'wave') {
  action = 'motion';
  params = { type: arg === 'left' ? 'wave_left' : 'wave_right' };
  response = `Waving ${arg === 'left' ? 'left' : 'right'} hand`;
} else if (cmd === 'shake' || cmd === 'handshake') {
  action = 'motion';
  params = { type: arg === 'left' ? 'handshake_left' : 'handshake_right' };
  response = 'Offering handshake';
} else if (cmd === 'emoji') {
  action = 'emoji';
  params = { id: parseInt(arg) || 90 };
  response = `Showing emoji ${params.id}`;
} else if (cmd === 'mode') {
  action = 'mode';
  params = { mode: arg || 'stand' };
  response = `Switching to ${params.mode} mode`;
} else if (cmd === 'bow') {
  action = 'motion';
  params = { type: 'bow' };
  response = 'Bowing';
} else if (cmd === 'cheer') {
  action = 'motion';
  params = { type: 'cheer' };
  response = 'Cheering!';
} else {
  response = `Unknown command: ${cmd}. Try: say, wave, shake, emoji, mode, bow, cheer`;
}

return [{ json: { action, params, response, hasAction: !!action } }];
